-- Guía editorial del caso confirmado; no registra fondos ni modifica operaciones.
INSERT INTO guia_proceso(slug,titulo,categoria,resumen,requisitos,ejemplo,version_contenido,revisada_el,estado) VALUES
('devolucion-parcial-nuevo-pago-100','Devolver $100 y pagar nuevamente el saldo','Cobranza',
'Devolución parcial de un pago de $400 y liquidación posterior de los $100 recuperados, con reporte familiar y validación administrativa.',
'Pago de prueba Validado de $400 completamente aplicado a un cargo de $400 sin ajustes ni devoluciones previas. Tutor activo autorizado para ver finanzas del alumno; cuenta bancaria activa compatible con saldo suficiente. Administrador persistido autorizado para consultar pagos/cuentas/adeudos, devolver y validar. Cada etapa parte del menú correspondiente. Adaptar fechas al día real sin futuros ni anteriores al pago. No ejecutar movimientos sólo por consultar esta guía.',
'Caso confirmado por el propietario: devolver $100 deja aplicado $300 y saldo $100; nuevo pago familiar de $100 validado deja aplicado acumulado $400 y saldo $0. S es el saldo antes de devolver, ya incluye el ingreso original. S - $100 + $100 = S; si S=$2,400.00 queda $2,300.00 tras devolver y $2,400.00 al validar el nuevo pago. Referencias TEST ficticias para pruebas; en operación usar datos auténticos.',
1,DATE '2026-10-07','CONFIRMADA');
INSERT INTO guia_proceso_permiso(guia_id,permiso_id)
SELECT g.id,p.id FROM guia_proceso g JOIN permiso p ON p.codigo=ANY(ARRAY['PAGO_LEER','PAGO_DEVOLVER','PAGO_VALIDAR','CARGO_ADMINISTRAR','CUENTA_FINANCIERA_LEER'])
WHERE g.slug='devolucion-parcial-nuevo-pago-100';
INSERT INTO guia_proceso_paso(guia_id,numero,titulo,perfil,modulo,instrucciones,ejemplo,resultado,precaucion,ruta)
SELECT g.id,v.* FROM guia_proceso g CROSS JOIN (VALUES
(1,$texto$Identificar el pago validado de $400$texto$,$texto$Administración$texto$,$texto$Pagos recibidos$texto$,$texto$1. Desde el menú lateral entra a Administración → Finanzas → Pagos recibidos. Busca el folio del pago validado de prueba por $400.00 (por ejemplo el reporte corregido TEST-CORREGIDO-400) y pulsa Aplicar filtros. 2. Pulsa Ver en la fila correcta. Comprueba alumno, concepto, importe original $400.00 y estado Validado; no uses el reporte Rechazado. 3. Abre Distribución: el abono activo debe ser $400.00 y el saldo del cargo $0.00. Anota matrícula, número de cargo, folio y cuenta receptora. 4. Abre Devoluciones y comprueba que no tenga devoluciones previas. Si ya realizaste esta prueba, consulta el historial; no repitas la operación sólo por leer la guía.$texto$,$texto$Pago validado $400.00, cargo total $400.00, aplicado $400.00, saldo $0.00.$texto$,$texto$Se identifica el registro exacto antes de mover dinero.$texto$,$texto$Parte de un pago de prueba ya liquidado. Si necesitas prepararlo, sigue la guía confirmada Rechazar un pago y corregir el reporte: $400 hasta su comprobación final, o utiliza otro caso controlado equivalente. No modifiques un pago operativo.$texto$,$texto$/admin/catalogos/pagos$texto$),
(2,$texto$Anotar el saldo antes de devolver$texto$,$texto$Administración$texto$,$texto$Cuentas financieras$texto$,$texto$1. Desde el menú lateral entra a Administración → Finanzas → Cuentas financieras. 2. Escribe código o nombre de la cuenta receptora anotada en Buscar y pulsa Aplicar filtros. 3. Anota Saldo actual como S; pulsa Editar si quieres consultarlo también en detalle. No cambies Saldo inicial. 4. Comprueba que es la cuenta correcta y tiene al menos $100.00. Este ejemplo devuelve y vuelve a recibir desde la misma cuenta; no selecciones otra para esta prueba.$texto$,$texto$S es el saldo antes de devolver, ya incluye el ingreso original de $400.00. Si S=$2,400.00, tras devolver debe quedar $2,300.00.$texto$,$texto$Saldo base registrado para comparar egreso y nuevo ingreso.$texto$,$texto$Si hay otros movimientos simultáneos, usa los movimientos vinculados para distinguirlos. Esta guía no prueba devoluciones desde otra cuenta.$texto$,$texto$/admin/catalogos/cuentas-financieras$texto$),
(3,$texto$Preparar y ejecutar la devolución parcial$texto$,$texto$Administración$texto$,$texto$Pagos recibidos → Ver → Devoluciones$texto$,$texto$1. Desde el menú lateral entra a Administración → Finanzas → Pagos recibidos; busca el folio anotado, pulsa Aplicar filtros y Ver. 2. Abre Devoluciones → Ejecutar devolución. Conserva Cuenta de origen protegida. No actives Devolver desde otra cuenta: no debe aparecer Motivo del cambio de cuenta. 3. Revisa Beneficiario; captura Fecha y hora actual, no futura ni anterior al pago. Elige Tipo de devolución Devolución parcial y Dinero a devolver 100.00. 4. Captura Referencia TEST-DEV-PARCIAL-100 y Motivo Prueba controlada de devolución parcial: devolver $100 y conservar $300 aplicados al cargo original. 5. En Abonos de los que se devolverá dinero marca sólo el abono de $400.00 del alumno/cargo anotado. Seleccionarlo identifica de dónde liberar dinero; no significa devolver todo el abono. 6. En Así quedaría la devolución comprueba Dinero a devolver $100.00, abono que permanecerá aplicado $300.00, deuda recuperada $100.00 y saldo por pagar después $100.00. Lee Se descontarán $100.00 de la cuenta correcta. 7. Si todo coincide pulsa Ejecutar devolución y publicar egreso una sola vez; espera el resultado.$texto$,$texto$Devolver $100.00, conservar $300.00 aplicados y recuperar deuda de $100.00.$texto$,$texto$Historial registra devolución de $100.00. El pago sigue Validado y conserva su importe original $400.00.$texto$,$texto$Esta operación registra salida de fondos, no un descuento. No agregues otro egreso manual ni canceles el pago. En uso real registra la devolución de dinero efectivamente realizada y su referencia auténtica; las referencias TEST son ilustrativas.$texto$,$texto$/admin/catalogos/pagos$texto$),
(4,$texto$Comprobar devolución, abono y egreso$texto$,$texto$Administración$texto$,$texto$Pagos, adeudos y cuentas$texto$,$texto$1. Desde el menú lateral entra a Administración → Finanzas → Pagos recibidos; busca el folio, pulsa Aplicar filtros → Ver → Devoluciones. Comprueba historial devuelto $100.00, cuenta, beneficiario, fecha y motivo. 2. En Distribución verifica que quedan $300.00 aplicados y Saldo actual que falta por pagar $100.00; el total del cargo sigue siendo $400.00. 3. Desde el menú lateral entra a Operación escolar → Cobranza escolar → Adeudos de alumnos; busca matrícula, pulsa Aplicar filtros y Ver del cargo anotado. Comprueba total $400.00, pagado acumulado $300.00 y saldo $100.00. 4. Desde el menú lateral entra a Administración → Finanzas → Cuentas financieras; busca cuenta y pulsa Aplicar filtros. Debe quedar S menos $100.00 sin otros movimientos.$texto$,$texto$Si S=$2,400.00, cuenta=$2,300.00; total del cargo $400.00, aplicado $300.00, deuda $100.00.$texto$,$texto$La devolución libera parte del abono y vuelve a dejar el cargo pendiente, sin alterar su importe original.$texto$,$texto$No confundas total del cargo con saldo pendiente. Devolver dinero no concede descuento y no elimina deuda.$texto$,$texto$/admin/catalogos/pagos$texto$),
(5,$texto$Consultar los $100 pendientes en el portal$texto$,$texto$Tutor$texto$,$texto$Portal familiar → Tus pagos$texto$,$texto$1. Abre /familias después de la dirección del sistema; usa ventana privada separada de administración e inicia con el tutor vinculado al alumno. 2. Desde el inicio selecciona al hijo del ejemplo y pulsa Tus pagos. 3. En Lo que falta por pagar identifica el mismo cargo por alumno, concepto y periodo: debe mostrar $100.00 pendientes. 4. Pulsa Reportar transferencia y enfoca Cargo pendiente del alumno; selecciona la sugerencia del cargo anotado, no otro cargo ni otro hijo. 5. Si no se ofrece, detente y revisa elegibilidad: vínculo financiero, estado, saldo, pagos en revisión y vencimiento. Si venció, administración puede habilitarlo desde Operación escolar → Cobranza escolar → Adeudos de alumnos → buscar matrícula → Aplicar filtros → Ver del cargo → Transferencia de cargo vencido → marcar autorización → motivo → Guardar autorización.$texto$,$texto$Saldo pendiente a reportar $100.00, no el importe original $400.00.$texto$,$texto$Se puede preparar un nuevo pago sobre el mismo adeudo.$texto$,$texto$No crees otra cuota/cargo para pagar el saldo. Habilitar un vencido no elimina recargos ni modifica fechas. Este caso no certifica condiciones que no se comprobaron.$texto$,NULL),
(6,$texto$Reportar el nuevo pago de $100$texto$,$texto$Tutor$texto$,$texto$Portal familiar → Reportar transferencia$texto$,$texto$1. Desde el inicio del portal familiar selecciona al hijo → Tus pagos → Reportar transferencia. En Cargo pendiente del alumno selecciona el cargo anotado; si ya lo elegiste, continúa en ese formulario. 2. Comprueba Total a transferir $100.00 protegido y ningún otro cargo seleccionado. 3. En Selecciona la cuenta destino elige la misma cuenta bancaria del ejemplo. 4. En Datos de la transferencia captura fecha/hora válidas y Referencia TEST-REPAGO-100. En Adjunta el comprobante selecciona el archivo de prueba correcto y legible por $100.00. 5. En Revisa y envía comprueba alumno, cargo, total, cuenta, referencia y archivo; pulsa Enviar transferencia a revisión. 6. Al volver a Tus pagos localiza el nuevo folio en Tus pagos y comprobantes; anótalo. Debe quedar En revisión; saldo del cargo todavía $100.00 y cuenta S menos $100.00.$texto$,$texto$Nuevo reporte $100.00 sobre el cargo existente, referencia de prueba TEST-REPAGO-100.$texto$,$texto$Se crea un pago nuevo para liquidar la deuda recuperada, pendiente de validación.$texto$,$texto$Este caso sí representa un nuevo pago tras devolución, distinto de corregir un archivo rechazado. En operación usa datos auténticos y confirma el ingreso real antes de validar. No envíes otro reporte del mismo saldo mientras éste está en revisión.$texto$,NULL),
(7,$texto$Validar el nuevo pago, no el original$texto$,$texto$Administración$texto$,$texto$Pagos recibidos → Ver → Gestión$texto$,$texto$1. Desde el menú lateral administrativo entra a Administración → Finanzas → Pagos recibidos. 2. Busca TEST-REPAGO-100 o el nuevo folio anotado, pulsa Aplicar filtros y Ver en la fila de $100.00 En revisión. 3. Abre Comprobantes, visualiza el archivo en otra pestaña y comprueba monto, referencia, fecha y recepción en la cuenta. 4. Abre Distribución y revisa que se solicita aplicar $100.00 al mismo cargo/alumno y que su saldo actual es $100.00. 5. En Gestión revisa la cuenta destino precargada: conserva la misma del ejemplo. Sólo después de comprobar todo pulsa Validar y publicar. 6. Comprueba que el nuevo pago queda Validado. No vuelvas a validar ni modificar el pago original de $400.00.$texto$,$texto$Un nuevo ingreso de $100.00 y aplicación de $100.00 al cargo.$texto$,$texto$El nuevo abono liquida los $100.00 pendientes y la cuenta recupera el importe devuelto.$texto$,$texto$Una imagen no acredita por sí sola recepción bancaria. No registres entrada manual adicional: validar ya publica su movimiento.$texto$,$texto$/admin/catalogos/pagos$texto$),
(8,$texto$Verificar liquidación final y conservar historial$texto$,$texto$Administración y tutor$texto$,$texto$Adeudos, cuentas y portal familiar$texto$,$texto$1. Desde el menú lateral entra a Operación escolar → Cobranza escolar → Adeudos de alumnos; busca matrícula → Aplicar filtros → Ver del mismo cargo. Verifica total $400.00, pagado acumulado $400.00 y saldo $0.00. 2. Desde el menú lateral entra a Administración → Finanzas → Cuentas financieras; busca la cuenta y pulsa Aplicar filtros. Su saldo vuelve a S, sin otras operaciones: egreso de $100.00 más nuevo ingreso de $100.00. 3. Desde el menú lateral entra a Administración → Finanzas → Pagos recibidos; busca el folio original → Aplicar filtros → Ver → Devoluciones. Debe conservar la devolución $100.00. Busca el folio nuevo y comprueba Validado por $100.00. 4. En la ventana familiar, desde el inicio selecciona el hijo → Tus pagos. Ese cargo ya no debe mostrar $100.00 pendientes. 5. En Tus pagos y comprobantes busca el nuevo folio; limpia mes/año, pulsa Buscar pagos y cambia de página si hace falta. Pulsa Ver comprobante PDF y revísalo en la nueva pestaña.$texto$,$texto$Pago original $400.00 menos devolución $100.00 más nuevo pago $100.00 = neto aplicado $400.00. Si S=$2,400.00, saldo final $2,400.00.$texto$,$texto$Caso confirmado por el propietario: egreso $100.00, deuda $100.00, nuevo pago familiar validado, cuenta incrementada $100.00 y adeudo final $0.00 sin pendiente familiar.$texto$,$texto$Conservar pago original, devolución y pago nuevo; no borrar ni compensar con descuento. La alternativa devolución más descuento manual se prueba por separado, sobre otro cargo, antes de incorporarla como confirmada.$texto$,$texto$/admin/catalogos/pagos$texto$)
) AS v(numero,titulo,perfil,modulo,instrucciones,ejemplo,resultado,precaucion,ruta)
WHERE g.slug='devolucion-parcial-nuevo-pago-100';
